#!/usr/bin/env python3
"""PNG analysis toolkit for reverse-engineering codesnap output.

Usage:
  python3 pngtool.py info FILE...            -> dimensions/colortype
  python3 pngtool.py px FILE X Y             -> pixel RGBA at X,Y
  python3 pngtool.py row FILE Y [X0 X1]      -> run-length compressed row colors
  python3 pngtool.py col FILE X [Y0 Y1]      -> run-length compressed column colors
  python3 pngtool.py uniq FILE               -> most common colors
  python3 pngtool.py bbox FILE R G B [A]     -> bounding box of pixels matching color
  python3 pngtool.py diff A B                -> bbox of differing pixels
  python3 pngtool.py crop FILE X0 Y0 X1 Y1 OUT -> write cropped png
  python3 pngtool.py art FILE [X0 Y0 X1 Y1 [W]] -> ascii art rendering
  python3 pngtool.py scan FILE               -> structural scan (window rect etc.)
"""
import struct, zlib, sys, collections

def read_chunks(p):
    d = open(p, 'rb').read()
    assert d[:8] == b'\x89PNG\r\n\x1a\n', p + ": not a png"
    i = 8; idat = b''; ihdr = None; chunks = []
    while i < len(d):
        ln = struct.unpack('>I', d[i:i+4])[0]; t = d[i+4:i+8]; data = d[i+8:i+8+ln]
        chunks.append((t.decode('latin1'), ln))
        if t == b'IHDR': ihdr = struct.unpack('>IIBBBBB', data)
        if t == b'IDAT': idat += data
        i += 12 + ln
    return ihdr, idat, chunks

_cache = {}

def load(p):
    if p in _cache: return _cache[p]
    ihdr, idat, ch = read_chunks(p)
    w, h, bd, ct, cm, fl, il = ihdr
    assert bd == 8 and il == 0, "unsupported"
    nch = {0:1, 2:3, 3:1, 4:2, 6:4}[ct]
    raw = zlib.decompress(idat)
    stride = w * nch
    out = bytearray(h * stride); prev = bytearray(stride)
    pos = 0
    for y in range(h):
        f = raw[pos]; pos += 1
        line = bytearray(raw[pos:pos+stride]); pos += stride
        if f == 1:
            for x in range(nch, stride): line[x] = (line[x] + line[x-nch]) & 255
        elif f == 2:
            for x in range(stride): line[x] = (line[x] + prev[x]) & 255
        elif f == 3:
            for x in range(stride):
                a = line[x-nch] if x >= nch else 0
                line[x] = (line[x] + ((a + prev[x]) >> 1)) & 255
        elif f == 4:
            for x in range(stride):
                a = line[x-nch] if x >= nch else 0
                b = prev[x]; c = prev[x-nch] if x >= nch else 0
                pa = abs(b-c); pb = abs(a-c); pc = abs(a+b-2*c)
                pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                line[x] = (line[x] + pr) & 255
        out[y*stride:(y+1)*stride] = line
        prev = line
    r = (w, h, nch, bytes(out))
    _cache[p] = r
    return r

def px(img, x, y):
    w, h, nch, data = img
    if x < 0 or y < 0 or x >= w or y >= h: return None
    o = (y*w + x) * nch
    t = tuple(data[o:o+nch])
    if nch == 4: return t
    if nch == 3: return t + (255,)
    if nch == 1: return (t[0],)*3 + (255,)
    return t

def hx(c):
    if c is None: return "OOB"
    if len(c) == 4 and c[3] == 255: return "#%02x%02x%02x" % c[:3]
    return "#%02x%02x%02x%02x" % c

def rle(seq):
    out = []
    for v in seq:
        if out and out[-1][0] == v: out[-1][1] += 1
        else: out.append([v, 1])
    return out

def main():
    cmd = sys.argv[1]
    a = sys.argv[2:]
    if cmd == 'info':
        for p in a:
            ihdr, idat, ch = read_chunks(p)
            print("%s: %dx%d colortype=%d bitdepth=%d idat=%d chunks=%s" % (p, ihdr[0], ihdr[1], ihdr[3], ihdr[2], len(idat), ch))
    elif cmd == 'px':
        img = load(a[0])
        for i in range(1, len(a), 2):
            x, y = int(a[i]), int(a[i+1])
            print("(%d,%d) = %s" % (x, y, hx(px(img, x, y))))
    elif cmd == 'row':
        img = load(a[0]); w, h, nch, _ = img
        y = int(a[1]); x0 = int(a[2]) if len(a) > 2 else 0; x1 = int(a[3]) if len(a) > 3 else w
        for v, n in rle(hx(px(img, x, y)) for x in range(x0, x1)):
            print("x=%d..%d (%d) %s" % (x0, x0+n-1, n, v)); x0 += n
    elif cmd == 'col':
        img = load(a[0]); w, h, nch, _ = img
        x = int(a[1]); y0 = int(a[2]) if len(a) > 2 else 0; y1 = int(a[3]) if len(a) > 3 else h
        for v, n in rle(hx(px(img, x, y)) for y in range(y0, y1)):
            print("y=%d..%d (%d) %s" % (y0, y0+n-1, n, v)); y0 += n
    elif cmd == 'uniq':
        img = load(a[0]); w, h, nch, _ = img
        c = collections.Counter()
        for y in range(h):
            for x in range(w): c[hx(px(img, x, y))] += 1
        n = int(a[1]) if len(a) > 1 else 30
        for k, v in c.most_common(n): print("%8d %s" % (v, k))
    elif cmd == 'bbox':
        img = load(a[0]); w, h, nch, _ = img
        target = a[1]
        xs = []; ys = []
        for y in range(h):
            for x in range(w):
                if hx(px(img, x, y)) == target: xs.append(x); ys.append(y)
        if xs: print("bbox x=%d..%d y=%d..%d count=%d" % (min(xs), max(xs), min(ys), max(ys), len(xs)))
        else: print("no match")
    elif cmd == 'diff':
        i1 = load(a[0]); i2 = load(a[1])
        if i1[0] != i2[0] or i1[1] != i2[1]:
            print("size differs %dx%d vs %dx%d" % (i1[0], i1[1], i2[0], i2[1])); return
        w, h = i1[0], i1[1]
        xs = []; ys = []; n = 0
        for y in range(h):
            for x in range(w):
                if px(i1, x, y) != px(i2, x, y): xs.append(x); ys.append(y); n += 1
        if n: print("diff bbox x=%d..%d y=%d..%d count=%d" % (min(xs), max(xs), min(ys), max(ys), n))
        else: print("identical pixels")
    elif cmd == 'art':
        img = load(a[0]); w, h, nch, _ = img
        x0, y0, x1, y1 = (int(v) for v in a[1:5]) if len(a) >= 5 else (0, 0, w, h)
        cols = int(a[5]) if len(a) > 5 else 100
        sx = max(1, (x1-x0)//cols)
        sy = sx * 2
        ramp = " .:-=+*#%@"
        for y in range(y0, y1, sy):
            line = ""
            for x in range(x0, x1, sx):
                p = px(img, x, y) or (0, 0, 0, 0)
                lum = (p[0]*30 + p[1]*59 + p[2]*11)//100
                if len(p) == 4: lum = lum*p[3]//255
                line += ramp[min(9, lum*10//256)]
            print(line)
    elif cmd == 'scan':
        img = load(a[0]); w, h, nch, _ = img
        print("size %dx%d nch=%d" % (w, h, nch))
        print("corners: TL=%s TR=%s BL=%s BR=%s" % (hx(px(img,0,0)), hx(px(img,w-1,0)), hx(px(img,0,h-1)), hx(px(img,w-1,h-1))))
        print("center=%s" % hx(px(img, w//2, h//2)))
        mid = h//2
        print("--- horizontal scan y=%d ---" % mid)
        x = 0
        for v, n in rle(hx(px(img, xx, mid)) for xx in range(w)):
            if n > 1 or True: print("  x=%d..%d (%d) %s" % (x, x+n-1, n, v))
            x += n
            if x > w: break
    else:
        print(__doc__)

main()

