//! DEFLATE (RFC 1951) and zlib (RFC 1950) compression.
//!
//! Written from scratch: an LZ77 matcher feeding a dynamic-Huffman block encoder.
//! Only compression is implemented; nothing here needs to inflate.

const WINDOW: usize = 32768;
const MIN_MATCH: usize = 3;
const MAX_MATCH: usize = 258;
const HASH_BITS: usize = 15;
const HASH_SIZE: usize = 1 << HASH_BITS;
const MAX_CHAIN: usize = 96;

/// Bit-level output, least-significant-bit first as DEFLATE requires.
struct BitWriter {
    out: Vec<u8>,
    acc: u32,
    nbits: u32,
}

impl BitWriter {
    fn new() -> Self {
        BitWriter { out: Vec::new(), acc: 0, nbits: 0 }
    }

    fn push(&mut self, value: u32, count: u32) {
        debug_assert!(count <= 24);
        self.acc |= (value & ((1u32 << count) - 1)) << self.nbits;
        self.nbits += count;
        while self.nbits >= 8 {
            self.out.push((self.acc & 0xff) as u8);
            self.acc >>= 8;
            self.nbits -= 8;
        }
    }

    /// Huffman codes are stored MSB-first but written LSB-first, so reverse.
    fn push_code(&mut self, code: u16, len: u8) {
        let mut rev = 0u32;
        for i in 0..len {
            rev |= (((code >> i) & 1) as u32) << (len - 1 - i);
        }
        self.push(rev, len as u32);
    }

    fn align(&mut self) {
        if self.nbits > 0 {
            self.out.push((self.acc & 0xff) as u8);
            self.acc = 0;
            self.nbits = 0;
        }
    }
}

/// Canonical Huffman code table built from symbol frequencies.
struct Huffman {
    lengths: Vec<u8>,
    codes: Vec<u16>,
}

impl Huffman {
    fn from_frequencies(freq: &[u32], max_len: u8) -> Huffman {
        let n = freq.len();
        let lengths = code_lengths(freq, max_len);
        let codes = canonical_codes(&lengths, max_len);
        debug_assert_eq!(lengths.len(), n);
        Huffman { lengths, codes }
    }

    fn cost(&self, freq: &[u32]) -> u64 {
        freq.iter().zip(self.lengths.iter()).map(|(f, l)| *f as u64 * *l as u64).sum()
    }

    fn emit(&self, w: &mut BitWriter, sym: usize) {
        w.push_code(self.codes[sym], self.lengths[sym]);
    }
}

/// Package-merge style length assignment: a simple Huffman tree build followed by
/// zlib-style overflow correction to respect `max_len`.
fn code_lengths(freq: &[u32], max_len: u8) -> Vec<u8> {
    let n = freq.len();
    let mut lengths = vec![0u8; n];
    let used: Vec<usize> = (0..n).filter(|&i| freq[i] > 0).collect();
    if used.is_empty() {
        return lengths;
    }
    if used.len() == 1 {
        lengths[used[0]] = 1;
        return lengths;
    }

    // Node arena: leaves first, then internal nodes.
    #[derive(Clone, Copy)]
    struct Node {
        weight: u64,
        left: i32,
        right: i32,
    }
    let mut nodes: Vec<Node> = used
        .iter()
        .map(|&i| Node { weight: freq[i] as u64, left: -(i as i32) - 1, right: -1 })
        .collect();
    // Repeatedly combine the two lowest-weight roots.
    let mut roots: Vec<usize> = (0..nodes.len()).collect();
    while roots.len() > 1 {
        roots.sort_by_key(|&r| (std::cmp::Reverse(nodes[r].weight), std::cmp::Reverse(r)));
        let a = roots.pop().unwrap();
        let b = roots.pop().unwrap();
        let w = nodes[a].weight + nodes[b].weight;
        nodes.push(Node { weight: w, left: a as i32, right: b as i32 });
        roots.push(nodes.len() - 1);
    }

    // Walk the tree to collect depths.
    let root = roots[0];
    let mut stack = vec![(root, 0u32)];
    let mut raw = vec![0u32; n];
    while let Some((idx, depth)) = stack.pop() {
        let node = nodes[idx];
        if node.right < 0 {
            let sym = (-(node.left) - 1) as usize;
            raw[sym] = depth.max(1);
        } else {
            stack.push((node.left as usize, depth + 1));
            stack.push((node.right as usize, depth + 1));
        }
    }

    // Overflow correction: repeatedly move the deepest symbols up by rebalancing
    // counts per length, mirroring the classic zlib approach.
    let mut counts = vec![0u32; 64];
    for &s in &used {
        counts[raw[s] as usize] += 1;
    }
    let ml = max_len as usize;
    let mut overflow: i64 = 0;
    for len in (ml + 1)..counts.len() {
        overflow += counts[len] as i64;
        counts[len] = 0;
    }
    if overflow > 0 {
        counts[ml] += overflow as u32;
