        // one symbol from a shorter length down one level.
        let mut remaining = overflow;
        while remaining > 0 {
            let mut len = ml - 1;
            while counts[len] == 0 {
                len -= 1;
            }
            counts[len] -= 1;
            counts[len + 1] += 2;
            counts[ml] -= 1;
            remaining -= 1;
        }
        // Reassign lengths in order of decreasing frequency for stability.
        let mut order: Vec<usize> = used.clone();
        order.sort_by_key(|&s| (std::cmp::Reverse(freq[s]), s));
        let mut it = order.into_iter();
        for len in 1..=ml {
            for _ in 0..counts[len] {
                if let Some(s) = it.next() {
                    lengths[s] = len as u8;
                }
            }
        }
        return lengths;
    }

    for &s in &used {
        lengths[s] = raw[s] as u8;
    }
    lengths
}

fn canonical_codes(lengths: &[u8], max_len: u8) -> Vec<u16> {
    let mut bl_count = vec![0u16; max_len as usize + 1];
    for &l in lengths {
        if l > 0 {
            bl_count[l as usize] += 1;
        }
    }
    let mut next_code = vec![0u16; max_len as usize + 2];
    let mut code = 0u16;
    for bits in 1..=max_len as usize {
        code = (code + bl_count[bits - 1]) << 1;
        next_code[bits] = code;
    }
    let mut codes = vec![0u16; lengths.len()];
    for (i, &l) in lengths.iter().enumerate() {
        if l > 0 {
            codes[i] = next_code[l as usize];
            next_code[l as usize] += 1;
        }
    }
    codes
}

