                if data[c + best_len] == data[i + best_len] && data[c] == data[i] {
                    let mut l = 0usize;
                    while l < max_len && data[c + l] == data[i + l] {
                        l += 1;
                    }
                    if l > best_len {
                        best_len = l;
                        best_dist = dist;
                        if l >= max_len {
                            break;
                        }
                    }
                }
                cand = prev[c];
                chain += 1;
            }
        }

        if best_len >= MIN_MATCH {
            tokens.push(Token::Match { len: best_len as u16, dist: best_dist as u16 });
            // Register the skipped positions so later matches can find them.
            for j in (i + 1)..(i + best_len).min(limit.saturating_sub(MIN_MATCH - 1)) {
                let hj = hash(data, j);
                prev[j] = head[hj];
                head[hj] = j as i32;
            }
            i += best_len;
        } else {
            tokens.push(Token::Literal(data[i]));
            i += 1;
        }
    }
    tokens
}

fn write_dynamic_block(w: &mut BitWriter, tokens: &[Token], last: bool) {
    let mut lit_freq = vec![0u32; 288];
    let mut dist_freq = vec![0u32; 30];
    for t in tokens {
        match *t {
            Token::Literal(b) => lit_freq[b as usize] += 1,
            Token::Match { len, dist } => {
                lit_freq[257 + length_symbol(len as usize)] += 1;
                dist_freq[dist_symbol(dist as usize)] += 1;
            }
        }
    }
    lit_freq[256] += 1; // end-of-block

    let lit = Huffman::from_frequencies(&lit_freq, 15);
    let has_dist = dist_freq.iter().any(|&f| f > 0);
    let mut dist_freq_eff = dist_freq.clone();
    if !has_dist {
        dist_freq_eff[0] = 1;
    }
    let dist = Huffman::from_frequencies(&dist_freq_eff, 15);

    // Trim trailing zero lengths.
    let mut hlit = 286;
    while hlit > 257 && lit.lengths[hlit - 1] == 0 {
        hlit -= 1;
    }
    let mut hdist = 30;
    while hdist > 1 && dist.lengths[hdist - 1] == 0 {
        hdist -= 1;
    }

    // Run-length encode the concatenated code lengths.
    let mut seq: Vec<u8> = Vec::with_capacity(hlit + hdist);
    seq.extend_from_slice(&lit.lengths[..hlit]);
    seq.extend_from_slice(&dist.lengths[..hdist]);
    let mut cl_syms: Vec<(u8, u8, u8)> = Vec::new(); // (symbol, extra_bits_value, extra_bit_count)
    let mut idx = 0;
    while idx < seq.len() {
        let v = seq[idx];
        let mut run = 1;
        while idx + run < seq.len() && seq[idx + run] == v {
            run += 1;
        }
        if v == 0 {
            let mut rem = run;
            while rem >= 11 {
                let take = rem.min(138);
                cl_syms.push((18, (take - 11) as u8, 7));
                rem -= take;
            }
            while rem >= 3 {
                let take = rem.min(10);
                cl_syms.push((17, (take - 3) as u8, 3));
                rem -= take;
            }
            for _ in 0..rem {
                cl_syms.push((0, 0, 0));
            }
        } else {
            cl_syms.push((v, 0, 0));
            let mut rem = run - 1;
            while rem >= 3 {
                let take = rem.min(6);
                cl_syms.push((16, (take - 3) as u8, 2));
                rem -= take;
            }
            for _ in 0..rem {
                cl_syms.push((v, 0, 0));
            }
        }
        idx += run;
    }

    let mut cl_freq = vec![0u32; 19];
    for (s, _, _) in &cl_syms {
        cl_freq[*s as usize] += 1;
    }
    let cl = Huffman::from_frequencies(&cl_freq, 7);
    let mut hclen = 19;
    while hclen > 4 && cl.lengths[CL_ORDER[hclen - 1]] == 0 {
        hclen -= 1;
    }

    w.push(if last { 1 } else { 0 }, 1);
    w.push(2, 2); // dynamic Huffman
    w.push((hlit - 257) as u32, 5);
    w.push((hdist - 1) as u32, 5);
    w.push((hclen - 4) as u32, 4);
    for i in 0..hclen {
        w.push(cl.lengths[CL_ORDER[i]] as u32, 3);
    }
    for (s, extra, nbits) in &cl_syms {
        cl.emit(w, *s as usize);
        if *nbits > 0 {
            w.push(*extra as u32, *nbits as u32);
        }
    }
    for t in tokens {
        match *t {
            Token::Literal(b) => lit.emit(w, b as usize),
            Token::Match { len, dist: d } => {
                let ls = length_symbol(len as usize);
                lit.emit(w, 257 + ls);
                let extra = LENGTH_EXTRA[ls];
                if extra > 0 {
                    w.push((len - LENGTH_BASE[ls]) as u32, extra as u32);
                }
                let ds = dist_symbol(d as usize);
                dist.emit(w, ds);
                let dextra = DIST_EXTRA[ds];
                if dextra > 0 {
                    w.push((d - DIST_BASE[ds]) as u32, dextra as u32);
                }
            }
        }
    }
    lit.emit(w, 256);
    let _ = lit.cost(&lit_freq);
}

/// Raw DEFLATE stream.
pub fn deflate(data: &[u8]) -> Vec<u8> {
    let mut w = BitWriter::new();
    if data.is_empty() {
        w.push(1, 1);
        w.push(2, 2);
        // Minimal empty dynamic block is awkward; use a stored empty block instead.
        let mut w2 = BitWriter::new();
        w2.push(1, 1);
        w2.push(0, 2);
        w2.align();
        w2.out.extend_from_slice(&[0, 0, 0xff, 0xff]);
        return w2.out;
    }
    // Split into blocks so the Huffman tables can adapt to local statistics.
    const BLOCK: usize = 1 << 18;
    let mut pos = 0;
    while pos < data.len() {
        let end = (pos + BLOCK).min(data.len());
        let tokens = lz77(&data[pos..end]);
        write_dynamic_block(&mut w, &tokens, end == data.len());
        pos = end;
    }
    w.align();
    w.out
}

fn adler32(data: &[u8]) -> u32 {
    let mut a: u32 = 1;
    let mut b: u32 = 0;
    for chunk in data.chunks(5552) {
        for &byte in chunk {
            a += byte as u32;
            b += a;
        }
        a %= 65521;
        b %= 65521;
    }
    (b << 16) | a
}

/// zlib container around a DEFLATE stream.
pub fn zlib_compress(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(data.len() / 3 + 64);
    // CMF: deflate, 32K window. FLG: FLEVEL=2 (default), check bits make it a multiple of 31.
    out.push(0x78);
    out.push(0x9c);
    out.extend_from_slice(&deflate(data));
    out.extend_from_slice(&adler32(data).to_be_bytes());
    out
}

