//! Minimal PNG writer (8-bit RGBA, non-interlaced).

use crate::deflate::zlib_compress;

fn crc32_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    let mut n = 0;
    while n < 256 {
        let mut c = n as u32;
        let mut k = 0;
        while k < 8 {
            c = if c & 1 != 0 { 0xEDB8_8320 ^ (c >> 1) } else { c >> 1 };
            k += 1;
        }
        table[n] = c;
        n += 1;
    }
    table
}

fn crc32(data: &[u8]) -> u32 {
    let table = crc32_table();
    let mut c = 0xFFFF_FFFFu32;
    for &b in data {
        c = table[((c ^ b as u32) & 0xff) as usize] ^ (c >> 8);
    }
    c ^ 0xFFFF_FFFF
}

fn chunk(out: &mut Vec<u8>, kind: &[u8; 4], body: &[u8]) {
    out.extend_from_slice(&(body.len() as u32).to_be_bytes());
    let mut with_kind = Vec::with_capacity(4 + body.len());
    with_kind.extend_from_slice(kind);
    with_kind.extend_from_slice(body);
    out.extend_from_slice(&with_kind);
    out.extend_from_slice(&crc32(&with_kind).to_be_bytes());
}

/// Pick the filter that minimises the sum of absolute differences, the same
/// heuristic every practical encoder uses.
fn filter_scanlines(width: usize, height: usize, rgba: &[u8]) -> Vec<u8> {
    let stride = width * 4;
    let mut out = Vec::with_capacity(height * (stride + 1));
    let mut prev = vec![0u8; stride];
    let mut candidates = vec![vec![0u8; stride]; 5];
    for y in 0..height {
        let line = &rgba[y * stride..(y + 1) * stride];
        for x in 0..stride {
            let a = if x >= 4 { line[x - 4] } else { 0 };
            let b = prev[x];
            let c = if x >= 4 { prev[x - 4] } else { 0 };
            candidates[0][x] = line[x];
            candidates[1][x] = line[x].wrapping_sub(a);
            candidates[2][x] = line[x].wrapping_sub(b);
            candidates[3][x] = line[x].wrapping_sub(((a as u16 + b as u16) / 2) as u8);
            let pa = (b as i16 - c as i16).abs();
            let pb = (a as i16 - c as i16).abs();
            let pc = (a as i16 + b as i16 - 2 * c as i16).abs();
            let pred = if pa <= pb && pa <= pc {
                a
            } else if pb <= pc {
                b
            } else {
                c
            };
            candidates[4][x] = line[x].wrapping_sub(pred);
        }
        let mut best = 0usize;
        let mut best_score = u64::MAX;
        for (i, cand) in candidates.iter().enumerate() {
            let score: u64 = cand.iter().map(|&v| if v < 128 { v as u64 } else { 256 - v as u64 }).sum();
            if score < best_score {
                best_score = score;
                best = i;
            }
        }
        out.push(best as u8);
        out.extend_from_slice(&candidates[best]);
        prev.copy_from_slice(line);
    }
    out
}

/// Encode an RGBA8 buffer as a PNG byte stream.
pub fn encode_rgba(width: u32, height: u32, rgba: &[u8]) -> Vec<u8> {
    assert_eq!(rgba.len(), (width as usize) * (height as usize) * 4);
    let mut out = Vec::new();
    out.extend_from_slice(&[0x89, b'P', b'N', b'G', 0x0d, 0x0a, 0x1a, 0x0a]);

    let mut ihdr = Vec::with_capacity(13);
    ihdr.extend_from_slice(&width.to_be_bytes());
    ihdr.extend_from_slice(&height.to_be_bytes());
    ihdr.push(8); // bit depth
    ihdr.push(6); // colour type: truecolour with alpha
    ihdr.push(0); // deflate
    ihdr.push(0); // adaptive filtering
    ihdr.push(0); // no interlace
    chunk(&mut out, b"IHDR", &ihdr);

    let filtered = filter_scanlines(width as usize, height as usize, rgba);
    let compressed = zlib_compress(&filtered);
    chunk(&mut out, b"IDAT", &compressed);
    chunk(&mut out, b"IEND", &[]);
    out
}

