        text.parse::<f64>().map(Json::Number).map_err(|_| self.error("invalid number"))
    }
}

fn utf8_len(b: u8) -> usize {
    if b < 0x80 {
        1
    } else if b >> 5 == 0b110 {
        2
    } else if b >> 4 == 0b1110 {
        3
    } else {
        4
    }
}

/// Convenience builder for object literals.
pub fn obj(entries: Vec<(&str, Json)>) -> Json {
    Json::Object(entries.into_iter().map(|(k, v)| (k.to_string(), v)).collect())
}

pub fn s(text: &str) -> Json {
    Json::String(text.to_string())
}

pub fn n(value: f64) -> Json {
    Json::Number(value)
}

/// Recursively flatten an object into dotted paths; handy for diagnostics.
pub fn flatten(value: &Json, prefix: &str, out: &mut BTreeMap<String, String>) {
    match value {
        Json::Object(entries) => {
            for (k, v) in entries {
                let path = if prefix.is_empty() { k.clone() } else { format!("{prefix}.{k}") };
                flatten(v, &path, out);
            }
        }
        other => {
            out.insert(prefix.to_string(), other.to_pretty());
        }
    }
}

