//! A small software rasteriser: RGBA canvas plus the handful of shapes the
//! snapshot renderer needs (rectangles, rounded rectangles, circles, linear
//! gradients, blurred shadows and glyph coverage masks).

use crate::color::Rgba;

#[derive(Clone)]
pub struct Canvas {
    pub width: usize,
    pub height: usize,
    /// Premultiplied-free straight RGBA, 4 bytes per pixel.
    pub data: Vec<u8>,
}

/// A greyscale coverage mask, used for shadows and glyphs.
#[derive(Clone)]
pub struct Mask {
    pub width: usize,
    pub height: usize,
    pub data: Vec<u8>,
}

impl Mask {
    pub fn new(width: usize, height: usize) -> Mask {
        Mask { width, height, data: vec![0u8; width * height] }
    }

    #[inline]
    pub fn get(&self, x: usize, y: usize) -> u8 {
        self.data[y * self.width + x]
    }

    #[inline]
    pub fn set(&mut self, x: usize, y: usize, v: u8) {
        self.data[y * self.width + x] = v;
    }
}

impl Canvas {
    pub fn new(width: usize, height: usize) -> Canvas {
        Canvas { width, height, data: vec![0u8; width * height * 4] }
    }

    pub fn filled(width: usize, height: usize, color: Rgba) -> Canvas {
        let mut c = Canvas::new(width, height);
        for px in c.data.chunks_exact_mut(4) {
            px[0] = color.r;
            px[1] = color.g;
            px[2] = color.b;
            px[3] = color.a;
        }
        c
    }

    #[inline]
    pub fn get(&self, x: usize, y: usize) -> Rgba {
        let o = (y * self.width + x) * 4;
        Rgba { r: self.data[o], g: self.data[o + 1], b: self.data[o + 2], a: self.data[o + 3] }
    }

    /// Source-over composite of a straight-alpha colour with extra coverage.
    #[inline]
    pub fn blend(&mut self, x: usize, y: usize, color: Rgba, coverage: u8) {
        if coverage == 0 || color.a == 0 {
            return;
        }
        if x >= self.width || y >= self.height {
            return;
        }
        let sa = mul255(color.a, coverage) as u32;
        if sa == 0 {
            return;
        }
        let o = (y * self.width + x) * 4;
        let da = self.data[o + 3] as u32;
        if sa == 255 {
            self.data[o] = color.r;
            self.data[o + 1] = color.g;
            self.data[o + 2] = color.b;
            self.data[o + 3] = 255;
            return;
        }
        let out_a = sa + da * (255 - sa) / 255;
        if out_a == 0 {
            self.data[o] = 0;
            self.data[o + 1] = 0;
            self.data[o + 2] = 0;
            self.data[o + 3] = 0;
            return;
        }
        for i in 0..3 {
            let src = color.channel(i) as u32;
            let dst = self.data[o + i] as u32;
            let num = src * sa * 255 + dst * da * (255 - sa);
            self.data[o + i] = ((num / 255 + out_a / 2) / out_a).min(255) as u8;
        }
        self.data[o + 3] = out_a as u8;
    }

    pub fn fill_rect(&mut self, x0: i32, y0: i32, x1: i32, y1: i32, color: Rgba) {
        let xs = x0.max(0) as usize;
        let ys = y0.max(0) as usize;
        let xe = (x1.max(0) as usize).min(self.width);
        let ye = (y1.max(0) as usize).min(self.height);
        for y in ys..ye {
            for x in xs..xe {
                self.blend(x, y, color, 255);
            }
        }
    }

    /// Anti-aliased axis-aligned rectangle with float edges.
    pub fn fill_rect_f(&mut self, x0: f32, y0: f32, x1: f32, y1: f32, color: Rgba) {
        if x1 <= x0 || y1 <= y0 {
            return;
        }
        let xs = x0.floor().max(0.0) as usize;
        let ys = y0.floor().max(0.0) as usize;
        let xe = (x1.ceil().max(0.0) as usize).min(self.width);
        let ye = (y1.ceil().max(0.0) as usize).min(self.height);
        for y in ys..ye {
            let cy = span_coverage(y as f32, y as f32 + 1.0, y0, y1);
            if cy <= 0.0 {
                continue;
            }
            for x in xs..xe {
                let cx = span_coverage(x as f32, x as f32 + 1.0, x0, x1);
                if cx <= 0.0 {
                    continue;
                }
                let cov = (cx * cy * 255.0).round().clamp(0.0, 255.0) as u8;
                self.blend(x, y, color, cov);
            }
        }
    }

    /// Composite another canvas on top at the given offset.
    pub fn draw_canvas(&mut self, other: &Canvas, ox: i32, oy: i32) {
        for y in 0..other.height {
            let ty = oy + y as i32;
            if ty < 0 || ty as usize >= self.height {
                continue;
            }
            for x in 0..other.width {
                let tx = ox + x as i32;
                if tx < 0 || tx as usize >= self.width {
                    continue;
                }
                let c = other.get(x, y);
                if c.a > 0 {
                    self.blend(tx as usize, ty as usize, c, 255);
                }
            }
        }
    }

    /// Paint a coverage mask in a single colour.
    pub fn draw_mask(&mut self, mask: &Mask, ox: i32, oy: i32, color: Rgba) {
        for y in 0..mask.height {
            let ty = oy + y as i32;
            if ty < 0 || ty as usize >= self.height {
                continue;
            }
            for x in 0..mask.width {
                let tx = ox + x as i32;
                if tx < 0 || tx as usize >= self.width {
                    continue;
                }
                let cov = mask.get(x, y);
                if cov > 0 {
                    self.blend(tx as usize, ty as usize, color, cov);
                }
            }
        }
    }

    pub fn to_rgba(&self) -> &[u8] {
        &self.data
    }
}

#[inline]
fn mul255(a: u8, b: u8) -> u8 {
    let t = a as u32 * b as u32 + 128;
    ((t + (t >> 8)) >> 8) as u8
}

#[inline]
fn span_coverage(pixel_lo: f32, pixel_hi: f32, lo: f32, hi: f32) -> f32 {
    let a = pixel_lo.max(lo);
    let b = pixel_hi.min(hi);
    (b - a).max(0.0)
}

/// Signed distance from a point to a rounded rectangle, negative inside.
fn rounded_rect_sdf(px: f32, py: f32, x0: f32, y0: f32, x1: f32, y1: f32, r: f32) -> f32 {
    let hw = (x1 - x0) * 0.5;
    let hh = (y1 - y0) * 0.5;
    let cx = x0 + hw;
    let cy = y0 + hh;
    let r = r.min(hw).min(hh).max(0.0);
    let qx = (px - cx).abs() - (hw - r);
    let qy = (py - cy).abs() - (hh - r);
    let ax = qx.max(0.0);
    let ay = qy.max(0.0);
    (ax * ax + ay * ay).sqrt() + qx.max(qy).min(0.0) - r
}

/// Coverage of a rounded rectangle at a pixel, using 4x4 supersampling near the
/// boundary and an exact answer in the interior.
fn rounded_rect_coverage(x: usize, y: usize, x0: f32, y0: f32, x1: f32, y1: f32, r: f32) -> f32 {
    let px = x as f32 + 0.5;
    let py = y as f32 + 0.5;
    let d = rounded_rect_sdf(px, py, x0, y0, x1, y1, r);
    if d < -1.0 {
        return 1.0;
    }
    if d > 1.0 {
        return 0.0;
    }
    const N: usize = 4;
    let mut hits = 0.0f32;
    for sy in 0..N {
        for sx in 0..N {
            let fx = x as f32 + (sx as f32 + 0.5) / N as f32;
            let fy = y as f32 + (sy as f32 + 0.5) / N as f32;
            if rounded_rect_sdf(fx, fy, x0, y0, x1, y1, r) <= 0.0 {
                hits += 1.0;
            }
        }
    }
    hits / (N * N) as f32
}

/// Build a coverage mask for a rounded rectangle occupying the whole mask.
pub fn rounded_rect_mask(width: usize, height: usize, radius: f32) -> Mask {
    let mut mask = Mask::new(width, height);
    let w = width as f32;
    let h = height as f32;
    for y in 0..height {
        for x in 0..width {
            let c = rounded_rect_coverage(x, y, 0.0, 0.0, w, h, radius);
            mask.set(x, y, (c * 255.0).round().clamp(0.0, 255.0) as u8);
        }
    }
    mask
}

impl Canvas {
    pub fn fill_rounded_rect(
        &mut self,
        x0: f32,
        y0: f32,
        x1: f32,
        y1: f32,
        radius: f32,
        color: Rgba,
    ) {
        let xs = x0.floor().max(0.0) as usize;
        let ys = y0.floor().max(0.0) as usize;
        let xe = (x1.ceil().max(0.0) as usize).min(self.width);
        let ye = (y1.ceil().max(0.0) as usize).min(self.height);
        for y in ys..ye {
            for x in xs..xe {
                let c = rounded_rect_coverage(x, y, x0, y0, x1, y1, radius);
                if c > 0.0 {
                    self.blend(x, y, color, (c * 255.0).round().clamp(0.0, 255.0) as u8);
                }
            }
        }
    }

    /// Stroke a rounded rectangle centred on the given path.
    pub fn stroke_rounded_rect(
        &mut self,
        x0: f32,
        y0: f32,
        x1: f32,
        y1: f32,
        radius: f32,
        width: f32,
        color: Rgba,
    ) {
        if width <= 0.0 {
            return;
        }
        let half = width * 0.5;
        let xs = (x0 - half).floor().max(0.0) as usize;
        let ys = (y0 - half).floor().max(0.0) as usize;
        let xe = ((x1 + half).ceil().max(0.0) as usize).min(self.width);
        let ye = ((y1 + half).ceil().max(0.0) as usize).min(self.height);
        for y in ys..ye {
            for x in xs..xe {
                // Coverage of the annulus = outer minus inner.
                let outer = rounded_rect_coverage(
                    x,
                    y,
                    x0 - half,
                    y0 - half,
                    x1 + half,
                    y1 + half,
                    radius + half,
                );
                if outer <= 0.0 {
                    continue;
                }
                let inner = rounded_rect_coverage(
                    x,
                    y,
                    x0 + half,
                    y0 + half,
                    x1 - half,
                    y1 - half,
                    (radius - half).max(0.0),
                );
                let c = (outer - inner).max(0.0);
                if c > 0.0 {
                    self.blend(x, y, color, (c * 255.0).round().clamp(0.0, 255.0) as u8);
                }
            }
        }
    }

    pub fn fill_circle(&mut self, cx: f32, cy: f32, r: f32, color: Rgba) {
        let xs = (cx - r).floor().max(0.0) as usize;
        let ys = (cy - r).floor().max(0.0) as usize;
        let xe = (((cx + r).ceil()).max(0.0) as usize).min(self.width);
        let ye = (((cy + r).ceil()).max(0.0) as usize).min(self.height);
        const N: usize = 4;
        for y in ys..ye {
            for x in xs..xe {
                let dx = x as f32 + 0.5 - cx;
                let dy = y as f32 + 0.5 - cy;
                let d = (dx * dx + dy * dy).sqrt() - r;
                let cov = if d < -1.0 {
                    1.0
                } else if d > 1.0 {
                    0.0
                } else {
                    let mut hits = 0.0f32;
                    for sy in 0..N {
                        for sx in 0..N {
                            let fx = x as f32 + (sx as f32 + 0.5) / N as f32 - cx;
                            let fy = y as f32 + (sy as f32 + 0.5) / N as f32 - cy;
                            if fx * fx + fy * fy <= r * r {
                                hits += 1.0;
                            }
                        }
                    }
                    hits / (N * N) as f32
                };
                if cov > 0.0 {
                    self.blend(x, y, color, (cov * 255.0).round().clamp(0.0, 255.0) as u8);
                }
            }
        }
    }
}

/// Three-pass box blur, the standard cheap approximation of a Gaussian.
pub fn blur_mask(mask: &Mask, sigma: f32) -> Mask {
    if sigma <= 0.0 {
        return mask.clone();
    }
    // Box sizes chosen so that three passes approximate a Gaussian of this sigma.
    let boxes = box_sizes_for_gauss(sigma, 3);
    let mut src = mask.clone();
    let mut dst = Mask::new(mask.width, mask.height);
    for b in boxes {
        if b <= 1 {
            continue;
        }
        box_blur_h(&src, &mut dst, b);
        box_blur_v(&dst, &mut src, b);
    }
    src
}

fn box_sizes_for_gauss(sigma: f32, n: usize) -> Vec<usize> {
    let w_ideal = ((12.0 * sigma * sigma / n as f32) + 1.0).sqrt();
    let mut wl = w_ideal.floor() as i32;
    if wl % 2 == 0 {
        wl -= 1;
    }
    let wu = wl + 2;
    let m_ideal = (12.0 * sigma * sigma
        - (n as f32) * (wl as f32) * (wl as f32)
        - 4.0 * (n as f32) * (wl as f32)
        - 3.0 * (n as f32))
        / (-4.0 * (wl as f32) - 4.0);
    let m = m_ideal.round() as i32;
    (0..n).map(|i| if (i as i32) < m { wl.max(1) as usize } else { wu.max(1) as usize }).collect()
}

fn box_blur_h(src: &Mask, dst: &mut Mask, size: usize) {
    let r = (size / 2) as i32;
    let w = src.width as i32;
    for y in 0..src.height {
        let row = y * src.width;
        let mut sum: u32 = 0;
        for x in -r..=r {
            let xi = x.clamp(0, w - 1) as usize;
            sum += src.data[row + xi] as u32;
        }
        let denom = (2 * r + 1) as u32;
        for x in 0..src.width {
            dst.data[row + x] = (sum / denom) as u8;
            let add = (x as i32 + r + 1).clamp(0, w - 1) as usize;
            let sub = (x as i32 - r).clamp(0, w - 1) as usize;
            sum = sum + src.data[row + add] as u32 - src.data[row + sub] as u32;
        }
    }
}

fn box_blur_v(src: &Mask, dst: &mut Mask, size: usize) {
    let r = (size / 2) as i32;
    let h = src.height as i32;
    for x in 0..src.width {
        let mut sum: u32 = 0;
        for y in -r..=r {
            let yi = y.clamp(0, h - 1) as usize;
            sum += src.data[yi * src.width + x] as u32;
        }
        let denom = (2 * r + 1) as u32;
        for y in 0..src.height {
            dst.data[y * src.width + x] = (sum / denom) as u8;
            let add = (y as i32 + r + 1).clamp(0, h - 1) as usize;
            let sub = (y as i32 - r).clamp(0, h - 1) as usize;
            sum = sum + src.data[add * src.width + x] as u32 - src.data[sub * src.width + x] as u32;
        }
    }
}

