    }

    pub fn fill_circle(&mut self, cx: f32, cy: f32, r: f32, color: Rgba) {
        let xs = (cx - r).floor().max(0.0) as usize;
        let ys = (cy - r).floor().max(0.0) as usize;
        let xe = (((cx + r).ceil()).max(0.0) as usize).min(self.width);
        let ye = (((cy + r).ceil()).max(0.0) as usize).min(self.height);
        const N: usize = 4;
        for y in ys..ye {
            for x in xs..xe {
                let dx = x as f32 + 0.5 - cx;
                let dy = y as f32 + 0.5 - cy;
                let d = (dx * dx + dy * dy).sqrt() - r;
                let cov = if d < -1.0 {
                    1.0
                } else if d > 1.0 {
