                } else {
                    let mut hits = 0.0f32;
                    for sy in 0..N {
                        for sx in 0..N {
                            let fx = x as f32 + (sx as f32 + 0.5) / N as f32 - cx;
                            let fy = y as f32 + (sy as f32 + 0.5) / N as f32 - cy;
                            if fx * fx + fy * fy <= r * r {
                                hits += 1.0;
                            }
                        }
                    }
                    hits / (N * N) as f32
                };
                if cov > 0.0 {
                    self.blend(x, y, color, (cov * 255.0).round().clamp(0.0, 255.0) as u8);
                }
            }
        }
    }
}

/// Three-pass box blur, the standard cheap approximation of a Gaussian.
pub fn blur_mask(mask: &Mask, sigma: f32) -> Mask {
    if sigma <= 0.0 {
