    }
    // Box sizes chosen so that three passes approximate a Gaussian of this sigma.
    let boxes = box_sizes_for_gauss(sigma, 3);
    let mut src = mask.clone();
    let mut dst = Mask::new(mask.width, mask.height);
    for b in boxes {
        if b <= 1 {
            continue;
        }
        box_blur_h(&src, &mut dst, b);
        box_blur_v(&dst, &mut src, b);
    }
    src
}

fn box_sizes_for_gauss(sigma: f32, n: usize) -> Vec<usize> {
    let w_ideal = ((12.0 * sigma * sigma / n as f32) + 1.0).sqrt();
    let mut wl = w_ideal.floor() as i32;
    if wl % 2 == 0 {
        wl -= 1;
    }
    let wu = wl + 2;
    let m_ideal = (12.0 * sigma * sigma
        - (n as f32) * (wl as f32) * (wl as f32)
        - 4.0 * (n as f32) * (wl as f32)
        - 3.0 * (n as f32))
        / (-4.0 * (wl as f32) - 4.0);
    let m = m_ideal.round() as i32;
    (0..n).map(|i| if (i as i32) < m { wl.max(1) as usize } else { wu.max(1) as usize }).collect()
}

fn box_blur_h(src: &Mask, dst: &mut Mask, size: usize) {
    let r = (size / 2) as i32;
    let w = src.width as i32;
    for y in 0..src.height {
        let row = y * src.width;
        let mut sum: u32 = 0;
        for x in -r..=r {
            let xi = x.clamp(0, w - 1) as usize;
            sum += src.data[row + xi] as u32;
        }
        let denom = (2 * r + 1) as u32;
        for x in 0..src.width {
            dst.data[row + x] = (sum / denom) as u8;
            let add = (x as i32 + r + 1).clamp(0, w - 1) as usize;
            let sub = (x as i32 - r).clamp(0, w - 1) as usize;
            sum = sum + src.data[row + add] as u32 - src.data[row + sub] as u32;
        }
    }
}

fn box_blur_v(src: &Mask, dst: &mut Mask, size: usize) {
    let r = (size / 2) as i32;
    let h = src.height as i32;
    for x in 0..src.width {
        let mut sum: u32 = 0;
        for y in -r..=r {
            let yi = y.clamp(0, h - 1) as usize;
            sum += src.data[yi * src.width + x] as u32;
        }
        let denom = (2 * r + 1) as u32;
        for y in 0..src.height {
            dst.data[y * src.width + x] = (sum / denom) as u8;
            let add = (y as i32 + r + 1).clamp(0, h - 1) as usize;
            let sub = (y as i32 - r).clamp(0, h - 1) as usize;
            sum = sum + src.data[add * src.width + x] as u32 - src.data[sub * src.width + x] as u32;
        }
    }
}

