//! Colour representation and parsing.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Rgba {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub a: u8,
}

impl Rgba {
    pub const TRANSPARENT: Rgba = Rgba { r: 0, g: 0, b: 0, a: 0 };

    pub const fn rgb(r: u8, g: u8, b: u8) -> Rgba {
        Rgba { r, g, b, a: 255 }
    }

    pub const fn rgba(r: u8, g: u8, b: u8, a: u8) -> Rgba {
        Rgba { r, g, b, a }
    }

    #[inline]
    pub fn channel(&self, i: usize) -> u8 {
        match i {
            0 => self.r,
            1 => self.g,
            _ => self.b,
        }
    }

    pub fn with_alpha(self, a: u8) -> Rgba {
        Rgba { a, ..self }
    }

    /// Blend `self` over an opaque background.
    pub fn over(self, bg: Rgba) -> Rgba {
        if self.a == 255 {
            return self;
        }
        let a = self.a as u32;
        let mix = |s: u8, d: u8| -> u8 {
            (((s as u32 * a) + (d as u32 * (255 - a)) + 127) / 255).min(255) as u8
        };
        Rgba { r: mix(self.r, bg.r), g: mix(self.g, bg.g), b: mix(self.b, bg.b), a: 255 }
    }

    pub fn to_hex(self) -> String {
        if self.a == 255 {
            format!("#{:02x}{:02x}{:02x}", self.r, self.g, self.b)
        } else {
            format!("#{:02x}{:02x}{:02x}{:02x}", self.r, self.g, self.b, self.a)
        }
    }
}

/// Parse a CSS-ish hex colour: `#rgb`, `#rgba`, `#rrggbb` or `#rrggbbaa`.
/// The leading `#` is optional.
pub fn parse_hex(text: &str) -> Option<Rgba> {
    let t = text.trim();
    let t = t.strip_prefix('#').unwrap_or(t);
    if !t.bytes().all(|b| b.is_ascii_hexdigit()) {
        return None;
    }
    let nib = |c: u8| -> u8 {
        match c {
            b'0'..=b'9' => c - b'0',
            b'a'..=b'f' => c - b'a' + 10,
            b'A'..=b'F' => c - b'A' + 10,
            _ => 0,
        }
    };
    let bytes = t.as_bytes();
    match bytes.len() {
        3 | 4 => {
            let expand = |i: usize| {
                let v = nib(bytes[i]);
                v * 17
            };
            Some(Rgba {
                r: expand(0),
                g: expand(1),
                b: expand(2),
                a: if bytes.len() == 4 { nib(bytes[3]) * 17 } else { 255 },
            })
        }
        6 | 8 => {
            let byte = |i: usize| nib(bytes[i * 2]) * 16 + nib(bytes[i * 2 + 1]);
            Some(Rgba {
                r: byte(0),
                g: byte(1),
                b: byte(2),
                a: if bytes.len() == 8 { byte(3) } else { 255 },
            })
        }
        _ => None,
    }
}

/// Linear interpolation in sRGB space.
pub fn lerp(a: Rgba, b: Rgba, t: f32) -> Rgba {
    let t = t.clamp(0.0, 1.0);
    let mix = |x: u8, y: u8| -> u8 {
        (x as f32 + (y as f32 - x as f32) * t).round().clamp(0.0, 255.0) as u8
    };
    Rgba { r: mix(a.r, b.r), g: mix(a.g, b.g), b: mix(a.b, b.b), a: mix(a.a, b.a) }
}

